        if new_weight < distances[neighbor]:
            distances[neighbor] = new_weight
            predecessors[neighbor] = node

    # Priority queue to keep track of nodes to visit, initially with the source node.
    from heapq import heappush, heappop
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we reach the target node, we can construct the path and return.
