    """
    Finds the shortest path from source to target in a weighted graph.

    Args:
    graph (dict): A dict mapping each node to a list of (neighbor, weight) pairs.
    source (Node): The starting node.
    target (Node): The target node.

    Returns:
    tuple: A tuple containing the shortest distance as a float and the shortest path as a list.
    If unreachable, returns (float("inf"), None).
    """
    import heapq

    def dijkstra(graph, source, target):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            # If we reached the target node, return the path
            if current_node == target:
                return distances[target], build_path(current_node, graph, distances)

            # Skip already processed nodes
            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                # Only consider the path if it's shorter
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        # If target is not reachable, return infinity and None
        return float('inf'), None

    def build_path(node, graph, distances):
        path = []
        while node:
            path.append(node)
            if distances[node] == float('inf'):
                break
            for neighbor, weight in graph[node]:
                if distances[neighbor] == distances[node] - weight:
                    node = neighbor
                    break
            else:
                node = None
        path.reverse()
        return path

    return dijkstra(graph, source, target)
